  generateOffers: async function (e, app) {
    e.preventDefault();
    var task = (await api.get("Workflow/ScheduledTask?$filter=AppId eq " + app.Id + " and contains(Name, 'offer')")).value[0];
    await api.post("Workflow/ScheduledTask(" + task.Id + ")/Execute?incrementNextExecution=false").then(() => {
      notification.success("Executed");
    }).catch((err) => error(err));
  },

