  updateTransactionLine: async function (e, app) {
    e.preventDefault();
    var updateTransactionDialog = new Dialog({ width: 1250, height: 220, title: "[resource_displayname[importCompanyData]]" });
    updateTransactionDialog.component = "CSVTransactionLineUpdater"
    updateTransactionDialog.init(() => CSVTransactionLineUpdater.init(app, $(".component[name=CSVTransactionLineUpdater]", updateTransactionDialog.element)));
  }

}
